-- Clean development schema. Use only in an EMPTY database, never import over an existing installation.

CREATE TABLE `entity` (entity_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, short_desc VARCHAR(255), expiry_date DATE NOT NULL, estab_date DATE NULL, additional_info TINYINT DEFAULT 0, default_home_page VARCHAR(255) DEFAULT '/', address TEXT NULL, email TEXT NULL, phone_num TEXT NULL, reg_num TEXT NULL, bank_ac_num TEXT NULL, bank_ifsc TEXT NULL, bank_name TEXT NULL, bank_location TEXT NULL, gst_no TEXT NULL, country TEXT NULL, state TEXT NULL, city TEXT NULL, area TEXT NULL, pincode TEXT NULL, s3_region TEXT NULL, s3_access_key_id TEXT NULL, s3_secret_access_key TEXT NULL, s3_bucket_name TEXT NULL, s3_cloudfront_url TEXT NULL, gmail_id TEXT NULL, app_password TEXT NULL, entity_image TEXT NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `branch` (entity_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, is_active TINYINT DEFAULT 1, allow_yend_entry TINYINT DEFAULT 0, branch_incharge_name TEXT NULL, address1 TEXT NULL, address2 TEXT NULL, pincode TEXT NULL, country TEXT NULL, state TEXT NULL, city TEXT NULL, area TEXT NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,branch_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `roles` (entity_id BIGINT NOT NULL, role_id BIGINT NOT NULL, role_name VARCHAR(150), is_superadmin TINYINT DEFAULT 0, is_admin TINYINT DEFAULT 0, is_staff TINYINT DEFAULT 1, is_active TINYINT DEFAULT 1, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,role_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `users` (entity_id BIGINT NOT NULL, user_id BIGINT NOT NULL, user_name VARCHAR(254) NOT NULL UNIQUE, user_password VARCHAR(255) NOT NULL, full_name TEXT, role_id BIGINT NOT NULL, user_active TINYINT DEFAULT 1, branch_id BIGINT NULL, desig_id BIGINT NULL, twofa_enabled TINYINT DEFAULT 0, joining_date DATE NULL, reporting_to BIGINT NULL, imageFile TEXT NULL, shift_code TEXT NULL, emp_structure_code TEXT NULL, pan_num TEXT NULL, uan TEXT NULL, esi TEXT NULL, bank_acc_num TEXT NULL, bank_ifsc_code TEXT NULL, bank_name TEXT NULL, bank_acc_type TEXT NULL, bank_location TEXT NULL, bank_branch_name TEXT NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `designation` (entity_id BIGINT NOT NULL, desig_id BIGINT NOT NULL, name VARCHAR(150), description TEXT, is_active TINYINT DEFAULT 1, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,desig_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `pages` (page_id BIGINT NOT NULL, page_name VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(150), description TEXT, superadmin_only TINYINT DEFAULT 0, access_for_all TINYINT DEFAULT 0, offline_enabled TINYINT DEFAULT 0, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (page_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `page_actions` (action_id BIGINT NOT NULL, page_id BIGINT NOT NULL, action_name VARCHAR(100), action_desc VARCHAR(255), cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (page_id,action_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `page_access` (entity_id BIGINT NOT NULL, role_id BIGINT NOT NULL, page_id BIGINT NOT NULL, access_to_add TINYINT DEFAULT 0, access_to_update TINYINT DEFAULT 0, access_to_delete TINYINT DEFAULT 0, access_to_export TINYINT DEFAULT 0, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,role_id,page_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `page_actions_access` (entity_id BIGINT NOT NULL, role_id BIGINT NOT NULL, page_id BIGINT NOT NULL, action_id BIGINT NOT NULL, action_name VARCHAR(100), cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,role_id,page_id,action_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `role_branch_access` (entity_id BIGINT NOT NULL, role_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,role_id,branch_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE session (session_id BIGINT AUTO_INCREMENT PRIMARY KEY,entity_id BIGINT NOT NULL,user_id BIGINT NOT NULL,token TEXT NOT NULL,log_type VARCHAR(2),login_time DATETIME,logout_time DATETIME NULL) ENGINE=InnoDB;

CREATE TABLE `crm_customers` (entity_id BIGINT NOT NULL, branch_id BIGINT NULL, assigned_to BIGINT NULL, customer_id BIGINT NOT NULL, company_name VARCHAR(255) NOT NULL, status VARCHAR(30) DEFAULT 'Active', total_revenue DECIMAL(18,2) DEFAULT 0, contact_name TEXT NULL, email TEXT NULL, phone TEXT NULL, mobile TEXT NULL, industry TEXT NULL, address TEXT NULL, city TEXT NULL, state TEXT NULL, country TEXT NULL, notes TEXT NULL, seed_tag VARCHAR(64) NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,customer_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `crm_leads` (entity_id BIGINT NOT NULL, branch_id BIGINT NULL, assigned_to BIGINT NULL, lead_id BIGINT NOT NULL, first_name VARCHAR(150), last_name VARCHAR(150), status VARCHAR(30) DEFAULT 'New', rating VARCHAR(20) DEFAULT 'Warm', estimated_value DECIMAL(18,2) DEFAULT 0, converted_customer_id BIGINT NULL, company TEXT NULL, email TEXT NULL, phone TEXT NULL, lead_source TEXT NULL, notes TEXT NULL, seed_tag VARCHAR(64) NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,lead_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `crm_deals` (entity_id BIGINT NOT NULL, branch_id BIGINT NULL, assigned_to BIGINT NULL, deal_id BIGINT NOT NULL, deal_name VARCHAR(255) NOT NULL, customer_id BIGINT NULL, lead_id BIGINT NULL, stage VARCHAR(30) DEFAULT 'Prospecting', status VARCHAR(30) DEFAULT 'Open', approval_status VARCHAR(30) DEFAULT 'Not Required', amount DECIMAL(18,2) DEFAULT 0, probability INT DEFAULT 20, expected_close_date DATE NULL, approved_by BIGINT NULL, notes TEXT NULL, approval_notes TEXT NULL, seed_tag VARCHAR(64) NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,deal_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `crm_activities` (entity_id BIGINT NOT NULL, branch_id BIGINT NULL, assigned_to BIGINT NULL, activity_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, activity_type VARCHAR(30), related_to_type VARCHAR(30), related_to_id BIGINT NULL, due_date DATETIME NULL, priority VARCHAR(30) DEFAULT 'Medium', status VARCHAR(30) DEFAULT 'Pending', notes TEXT, seed_tag VARCHAR(64) NULL, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (entity_id,activity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `country` (COUNTRY_CODE VARCHAR(10), COUNTRY_ISO VARCHAR(10), COUNTRY_NAME VARCHAR(100), COUNTRY_PHONE VARCHAR(20), cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (COUNTRY_CODE)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `states` (STATE_CODE VARCHAR(10), COUNTRY_CODE VARCHAR(10), TIN_CODE VARCHAR(10), STATE_NAME VARCHAR(100), STATE_GST_CODE VARCHAR(10), GST VARCHAR(10), cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (STATE_CODE)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `cities` (CITY_CODE VARCHAR(10), STATE_CODE VARCHAR(10), CITY_NAME VARCHAR(100), cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (CITY_CODE)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bank_master` (BANK_CODE VARCHAR(20), BANK_DESC VARCHAR(150), ORDER_SL INT, cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (BANK_CODE)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bank_account_type` (ACNT_TYPE VARCHAR(20), ACNT_DESC VARCHAR(100), cr_by BIGINT NULL, cr_on DATETIME DEFAULT CURRENT_TIMESTAMP, mo_by BIGINT NULL, mo_on DATETIME NULL, PRIMARY KEY (ACNT_TYPE)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
